"use strict";
/* =============================================================================
   @MausamMitra frontend
   Vanilla JS, no build step. Talks to the FastAPI backend in ../backend.
   Sections: state & settings, connection, markdown, chat (streaming), voice,
   forecast (map + chart + advisory), alerts (+ push-style notifications),
   tabs, PWA install/service worker.
   ============================================================================= */

// ---------------------------------------------------------------- state
// Empty string = same-origin: the backend now serves this frontend itself
// (single Render web service), so relative fetches ("/forecast", "/chat", …)
// just work without needing a separate API host.
const DEFAULT_API_BASE = "";
let apiBase = localStorage.getItem("wgpt_api_base") || DEFAULT_API_BASE;
let language = localStorage.getItem("wgpt_lang") || "en";
let sessionId = "web-" + Math.random().toString(36).slice(2, 10);
let notifyEnabled = localStorage.getItem("wgpt_notify") === "1";

let map, marker, chart;
let selectedLocation = null; // {name, admin1, lat, lon}
let knownAlerts = []; // accumulated {date, severity, type, message, source}
let lastSeenAlertsCount = 0;

// ---------------------------------------------------------------- elements
const el = (id) => document.getElementById(id);
const log = el("log"), inp = el("inp"), sendBtn = el("send"), micBtn = el("mic"), suggBox = el("sugg");
const connDot = el("connDot");
const demoBadge = el("demoBadge");
const langSelect = el("langSelect");
const settingsBtn = el("settingsBtn"), settingsModal = el("settingsModal"), apiBaseInput = el("apiBaseInput"), saveSettingsBtn = el("saveSettingsBtn"), closeSettingsBtn = el("closeSettingsBtn");
const alertTicker = el("alertTicker"), tickerTrack = el("tickerTrack");
const placeSearch = el("placeSearch"), suggestDropdown = el("suggestDropdown");
const mapDiv = el("map");
const forecastEmpty = el("forecastEmpty"), forecastEmptyText = el("forecastEmptyText"), forecastSettingsBtn = el("forecastSettingsBtn"), forecastContent = el("forecastContent"), dialGrid = el("dialGrid"), weatherHero = el("weatherHero"), forecastStrip = el("forecastStrip");
const useLocationBtn = el("useLocationBtn"), useLocationBtnEmpty = el("useLocationBtnEmpty");
const warnBanner = el("warnBanner"), warnLabel = el("warnLabel"), warnDesc = el("warnDesc");
const disasterToggle = el("disasterToggle"), disasterChevron = el("disasterChevron"), disasterBody = el("disasterBody"), disasterSummary = el("disasterSummary"), disasterSteps = el("disasterSteps"), disasterSmsBtn = el("disasterSmsBtn");
const windCompass = el("windCompass"), windReadout = el("windReadout"), pressureGauge = el("pressureGauge"), pressureReadout = el("pressureReadout"), humidityGauge = el("humidityGauge"), humidityReadout = el("humidityReadout");
const radarDisplay = el("radarDisplay"), radarSlider = el("radarSlider"), radarTime = el("radarTime"), radarPlayBtn = el("radarPlayBtn");
const cropSelect = el("cropSelect"), advisoryBtn = el("advisoryBtn"), advisoryBox = el("advisoryBox");
const notifySwitch = el("notifySwitch"), alertsList = el("alertsList"), alertBadge = el("alertBadge");
const helplineCard = el("helplineCard"), helplineActions = el("helplineActions"), helplineSub = el("helplineSub"), helplineSpeakBtn = el("helplineSpeakBtn");
const installToast = el("installToast"), installBtn = el("installBtn"), installDismissBtn = el("installDismissBtn");

const LANG_BCP47 = { en: "en", hi: "hi", gu: "gu", mr: "mr", ta: "ta", te: "te", kn: "kn", bn: "bn", pa: "pa", ml: "ml" };
const LANGUAGE_NAMES = {
  en: "English", hi: "हिंदी", gu: "ગુજરાતી", mr: "मराठी", ta: "தமிழ்",
  te: "తెలుగు", kn: "ಕನ್ನಡ", bn: "বাংলা", pa: "ਪੰਜਾਬੀ", ml: "മലയാളം",
};

