    mr: "संध्याकाळचा पाऊस येण्यापूर्वी आत्ताच शेतातील पाणी निचरा वाहिन्या तपासा आणि साफ करा.",
    ta: "மாலை மழை வருவதற்கு முன் இப்போதே வயல் வடிகால் சேனல்களை சரிபார்த்து சுத்தம் செய்யவும்.",
    te: "సాయంత్రం వర్షం రాకముందే ఇప్పుడే పొలం డ్రైనేజీ కాలువలను తనిఖీ చేసి శుభ్రం చేయండి.",
    kn: "ಸಂಜೆಯ ಮಳೆ ಬರುವ ಮೊದಲು ಈಗಲೇ ಹೊಲದ ಒಳಚರಂಡಿ ಕಾಲುವೆಗಳನ್ನು ಪರಿಶೀಲಿಸಿ ಸ್ವಚ್ಛಗೊಳಿಸಿ.",
    bn: "সন্ধ্যার বৃষ্টি আসার আগে এখনই মাঠের নিষ্কাশন নালা পরীক্ষা করে পরিষ্কার করুন।",
