function renderSuggestionChips() {
  suggBox.innerHTML = "";
  const icons = ["🌧️", "🌱", "⛈️", "📈"]; // matches the fixed order of the 4 canonical questions
  (SUGGESTIONS_I18N[language] || SUGGESTIONS_I18N.en).forEach(({ send, label }, i) => {
    const c = document.createElement("div"); c.className = "sugg"; c.textContent = `${icons[i] || "💬"} ${label}`;
    // Send exactly what's shown — live Gemini understands the question in
    // any language directly, so there's no need to secretly swap in the
    // English version underneath (that used to make the chat bubble show
    // different text than what was actually tapped, which was confusing).
    // Demo Mode's simple keyword matching (looks for "ahmedabad" etc. in
    // English) won't recognize a non-English chip tap — it'll show its
    // "try one of these" fallback instead of a canned answer, which is an
    // acceptable trade-off since Demo Mode is a quota-free dev aid, not
    // the real experience judges see.
    c.onclick = () => sendMessage(label);
    suggBox.appendChild(c);
  });
}
renderSuggestionChips();

let welcomeMsgEl = addMsg("bot", t("welcomeMsg"));
function updateWelcomeMessage() {
  if (welcomeMsgEl) welcomeMsgEl.innerHTML = renderMarkdown(t("welcomeMsg"));
}

// Pull alerts out of a chat turn's tool trace (get_weather_briefing or evaluate_alerts)
// so the ticker/Alerts tab/push notifications stay in sync with the conversation.
function applyTrace(trace) {
  for (const step of trace) {
    const out = step.output || {};
    let alerts = null;
    if (step.tool === "get_weather_briefing" && Array.isArray(out.alerts)) alerts = out.alerts;
    if (step.tool === "evaluate_alerts" && Array.isArray(out.alerts)) alerts = out.alerts;
    if (alerts) addAlerts(alerts, "chat");
  }
}

// ============================================================================
// VOICE INPUT (Web Speech API — swap for Bhashini ASR for full Indic coverage)
// ============================================================================
const voiceWave = el("voiceWave");
const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
if (SR) {
  const rec = new SR();
  rec.interimResults = false;
  let listening = false;
  rec.onresult = (e) => { inp.value = e.results[0][0].transcript; sendBtn.onclick(); };
  rec.onend = () => { listening = false; micBtn.classList.remove("listening"); voiceWave.classList.add("hidden"); };
  micBtn.onclick = () => {
    showIconTooltip(micBtn, t("micTooltip"));
    if (listening) { rec.stop(); return; }
    rec.lang = TTS_LOCALES[language] || "en-IN";
    listening = true; micBtn.classList.add("listening"); voiceWave.classList.remove("hidden");
    try { rec.start(); } catch { listening = false; micBtn.classList.remove("listening"); voiceWave.classList.add("hidden"); }
  };
} else {
  micBtn.onclick = () => alert("Voice input isn't supported in this browser — try Chrome or Edge.");
}

// ============================================================================
// TYPE-IN-NATIVE-SCRIPT (phonetic transliteration as you type)
// When a non-English language is selected, typing in Latin letters and
// hitting space/Enter converts the word you just finished into that
// language's native script — the same "type kem cho, see કેમ છો" pattern
// used by Google Input Tools / Gboard's transliteration mode. Uses Google's
// public transliteration lookup for the actual phonetic mapping (accurate
// fuzzy matching is hard to get right by hand for 9 scripts); if that
// lookup is ever unreachable (offline, endpoint retired), typing just
// silently stays in plain Latin letters instead of breaking the input.
// ============================================================================
const TRANSLIT_ITC = {
  hi: "hi-t-i0-und", gu: "gu-t-i0-und", mr: "mr-t-i0-und", ta: "ta-t-i0-und",
  te: "te-t-i0-und", kn: "kn-t-i0-und", bn: "bn-t-i0-und", pa: "pa-t-i0-und",
  ml: "ml-t-i0-und",
};

async function transliterateWord(word, itc) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 3000);
  try {
    const url = `https://inputtools.google.com/request?text=${encodeURIComponent(word)}` +
      `&itc=${itc}&num=1&cp=0&cs=1&ie=utf-8&oe=utf-8&app=mausammitra`;
    const r = await fetch(url, { signal: controller.signal });
    if (!r.ok) return null;
    const data = await r.json();
    return data?.[0] === "SUCCESS" ? (data[1]?.[0]?.[1]?.[0] || null) : null;
  } catch {
    return null; // offline / blocked / endpoint down — fail silently, keep plain text
  } finally {
    clearTimeout(timeout);
  }
}

function insertAtCursor(text) {
  const start = inp.selectionStart ?? inp.value.length;
  const end = inp.selectionEnd ?? inp.value.length;
  inp.value = inp.value.slice(0, start) + text + inp.value.slice(end);
  const newPos = start + text.length;
  inp.setSelectionRange(newPos, newPos);
}

// Shared by BOTH the physical/hardware keyboard's space/Enter handling AND
// the on-screen keyboard's Space/Send keys below — one code path so the
// two can never drift out of sync with each other.
async function handleWordBoundaryKey(key) {
  const isEnter = key === "Enter";
  const itc = TRANSLIT_ITC[language];
  const pos = inp.selectionStart;
  const before = inp.value.slice(0, pos);
  const match = itc ? before.match(/([A-Za-z']+)$/) : null; // the Latin word just finished, if transliteration applies
  if (match) {
    const word = match[1];
    const translit = await transliterateWord(word, itc);
    const replacement = translit || word;
    const start = pos - word.length;
    const rest = inp.value.slice(pos);
    const insertion = replacement + (isEnter ? "" : " ");
    inp.value = inp.value.slice(0, start) + insertion + rest;
    const newPos = start + insertion.length;
    inp.setSelectionRange(newPos, newPos);
  } else if (!isEnter) {
    insertAtCursor(" ");
  }
  if (isEnter) sendBtn.onclick();
}

inp.addEventListener("keydown", async (e) => {
  if (e.key !== " " && e.key !== "Enter") return;
  e.preventDefault(); // hold the keystroke so the word doesn't jump around mid-swap
  await handleWordBoundaryKey(e.key);
});

// ============================================================================
// ON-SCREEN VIRTUAL KEYBOARD — a fully in-app keyboard, so no OS/native
// keyboard is needed at all while it's open. Keys type the SELECTED
// LANGUAGE's own characters directly (no separate Latin-then-convert step
// like the physical-keyboard transliteration feature) — what you see on
// the key is exactly what lands in the text field.
//
// Trade-off worth knowing: Brahmic scripts build real words by combining a
// consonant's base form with vowel signs (matras) and conjunct rules — a
// direct one-key-one-character keyboard like this (same approach real
// "native" on-screen keyboards for these scripts use) produces readable,
// recognizable script, but won't auto-correct grammar/spelling the way the
// phonetic transliteration on a physical keyboard does. For a fully
// accurate written sentence, the physical-keyboard transliteration path
// (type "kem cho", get corrected native spelling) is still the more
// linguistically accurate option — this on-screen keyboard is the direct,
// literal alternative for when no physical keyboard is available at all.
// ============================================================================
const kbToggleBtn = el("kbToggleBtn"), onscreenKeyboard = el("onscreenKeyboard"), kbSuggestBar = el("kbSuggestBar");

// A small domain-relevant word list per language (weather/farming terms
